text:
{
  "title": "اتفاقية الخدمات ومعالجة البيانات",
  "planted": [
    {
      "slot": "p1",
      "text": "تحتفظ الشركة بصفتها جهة التحكم بحق استخدام البيانات المجمعة لأي غرض تشغيلي تراه مناسباً حالياً أو مستقبلاً، بما في ذلك تطوير المنتجات وأغراض التحليل الداخلي غير المذكورة صراحة في هذه الاتفاقية ودون الحاجة للحصول على إذن إضافي."
    },
    {
      "slot": "p2",
      "text": "يحق للمورد التعاقد من الباطن مع أي أطراف ثالثة لتقديم الخدمات أو معالجة البيانات المرتبطة بها وفقاً لتقديره التجاري، وتُعفى أنظمة المورد الداخلية من أي التزامات تخص التدقيق المباشر من قبل الشركة."
    },
    {
      "slot": "p3",
      "text": "في حال وقوع أي حادث أمني أو وصول غير مصرح به إلى البيانات، يقوم المورد بتقييم الموقف وفقاً لتقديره المطلق لتحديد ما إذا كان إشعار الشركة ملائماً، ودون الارتباط بأي جداول زمنية محددة مسبقاً."
    },
    {
      "slot": "p4",
      "text": "يتم الاحتفاظ بملفات السجلات والبيانات التشغيلية للمدة الزمنية اللازمة حصراً لإتمام الأغراض المتعاقد عليها، على أن تُتخذ الإجراءات اللازمة لإتلافها فور انتفاء الحاجة التشغيلية لها ما لم تقتضِ متطلبات التدقيق المالي استمرار الاحتفاظ بها."
    }
  ],
  "neutral": [
    "تلتزم الشركة بسداد الرسوم المتفق عليها لصالح المورد خلال ثلاثين روزنامة من تاريخ استلام الفطورة الضريبية المطابقة للمواصفات.",
    "تبدأ هذه الاتفاقية من تاريخ توقيع الطرفين وتظل سارية لمدة عام كامل، وتجدد تلقائياً ما لم يقم أحد الطرفين بإشعار الطرف الآخر برغبته في عدم التجديد قبل ثلاثين يوماً على الأقل.",
    "تقتصر المسؤولية القانونية لأي من الطرفين في مواجهة الطرف الآخر عن الأضرار المباشرة الناجمة عن الإهمال الجسيم على إجمالي الأتعاب المدفوعة خلال الأشهر الستة السابقة لوقوع الضرر.",
    "تخضع هذه الاتفاقية وتفسر وفقاً لأنظمة المملكة العربية السعودية، وتختص الجهات القضائية بالفصل في أي نزاع قد ينشأ عنها.",
    "تظل حقوق الملكية الفكرية للبرمجيات والأدوات التقنية المقدمة مملوكة حصرياً للمورد، وتمنح الشركة ترخيصاً غير حصري لاستخدامها طوال مدة سريان الاتفاقية."
  ]
}
